"""Export public synthetic stage-6..8 conformance data; never reads photos/settings.

--write updates generated files. --check (the default) detects drift against the PC authority.
This is not a DNG decoder or a whole Stage Clear conformance test.
"""
from __future__ import annotations

import argparse
import gzip
import ast
from pathlib import Path

import numpy as np

import r6_diagnose as r
import r7_look as k
import r10h_refine as h
import r10i_highlights as hi
import stage_clear as sc
from test_stage_clear import scene

ROOT = Path(__file__).resolve().parents[2]
CONSTANTS = ROOT / "app/src/main/java/dev/cinematic/p0/raw/StageClearV1.kt"
FIXTURE = ROOT / "app/src/test/resources/stage_clear_protections_v1.csv.gz"


def matrix(function: str, module, name: str) -> list[list[float]]:
    """Read literal matrices from the authority, without maintaining a second copy."""
    tree = ast.parse(Path(module.__file__).read_text(encoding="utf-8"))
    fn = next(n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == function)
    assignment = next(n for n in fn.body if isinstance(n, ast.Assign)
                      and any(isinstance(t, ast.Name) and t.id == name for t in n.targets))
    return ast.literal_eval(assignment.value.args[0])


def number(v: float) -> str:
    return format(float(v), ".10g")


def constants() -> str:
    _, knee, slope, lift, _ = h.LEVELS[h.CHOSEN_LEVEL]
    # vivid=.24 is selected inside stage_clear.iconic_layer; keep a source assertion below.
    tree = ast.parse(Path(sc.__file__).read_text(encoding="utf-8"))
    layer = next(n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == "iconic_layer")
    cap_call = next(n for n in ast.walk(layer) if isinstance(n, ast.Call)
                    and isinstance(n.func, ast.Attribute) and n.func.attr == "skin_chroma_cap")
    vivid = ast.literal_eval(cap_call.args[-1])
    scalars = {"DEFAULT_STRENGTH": sc.DEFAULT_STRENGTH, "SKIN_KNEE": knee,
               "SKIN_SLOPE": slope, "SKIN_HUE_LIFT": lift, "SKIN_VIVID": vivid,
               "RED_TARGET": h.RED_TARGET, "SHOULDER": hi.SHOULDER,
               "FACE_LIMIT": hi.FACE_LIMIT, "MAX_CUT_EV": hi.MAX_CUT}
    lines = ["// Generated by tools/raw_baseline/export_android_protections.py --write. Do not edit.",
             "package dev.cinematic.p0.raw", "", "internal object StageClearV1 {",
             f'    const val VERSION = "{sc.VERSION}"']
    lines += [f"    const val {key} = {number(value)}" + (".0" if float(value).is_integer() else "")
              for key, value in scalars.items()]
    arrays = {"LUMA": [r.LUMA.tolist()], "RGB_TO_LMS": matrix("oklab", r, "m1"),
              "LMS_TO_LAB": matrix("oklab", r, "m2"),
              "LAB_TO_LMS": matrix("oklab_to_linear", k, "m2_inv"),
              "LMS_TO_RGB": matrix("oklab_to_linear", k, "m1_inv")}
    # Accessors return copies: callers cannot mutate the shared numerical definition.
    for name, rows in arrays.items():
        lines.append(f"    val {name}: FloatArray get() = floatArrayOf(")
        for row in rows:
            lines.append("        " + ", ".join(number(np.float32(v)) + "f" for v in row) + ",")
        lines.append("    )")
    return "\n".join(lines + ["}", ""])


def synthetic_layer(values: np.ndarray) -> np.ndarray:
    """Nonlinear stand-in for stages 2..5, explicitly not the Stage Clear iconic layer."""
    return (values + np.float32(.06) * values * values).astype(np.float32)


def cases():
    yy, xx = np.mgrid[:10, :10].astype(np.float32)
    ramp = np.stack((.1 + xx * .15, .08 + yy * .12, .04 + (xx + yy) * .035), -1)
    mask = np.ones((10, 10), dtype=np.float32)
    yield "ramp-face", ramp, mask
    yield "no-face", ramp, mask * 0
    yield "mask-at-half", ramp, mask * .5
    for count in (49, 50):
        partial = np.zeros(100, dtype=np.float32)
        partial[:count] = 1
        yield f"face-{count}", ramp + 1.5, partial.reshape(10, 10)
    yield "soft-face", ramp, np.linspace(0, 1, 100, dtype=np.float32).reshape(10, 10)
    yield "black", ramp * 0, mask
    swatches = np.array([[.62, .3, .22], [.8, .16, .25], [2., .02, .01],
                         [-.2, .08, 1.4], [-.2, -.1, -.05], [1.3, 1.3, 1.3],
                         [.0031308, .0031308, .0031308], [.01, .01, .01],
                         [.60382734, .60382734, .60382734], [.7874123, .7874123, .7874123]], dtype=np.float32)
    yield "colour-and-transfer-edges", np.tile(swatches, (10, 1, 1)), mask
    image, faces, _ = scene()
    yield "sampled-original-stage", image[::9, ::10], faces[::9, ::10]


def fixture() -> str:
    lines = ["# synthetic stage-6..8 only; float32 RGB linear sRGB/D65; no photo data",
             "# CASE,name,width,height,face_factor; PIX,inputRGB,mask,capRGB,shoulderRGB,finishRGB"]
    _, knee, slope, lift, _ = h.LEVELS[h.CHOSEN_LEVEL]
    for name, image, faces in cases():
        cap = lambda values: h.skin_chroma_cap(values, faces, knee, slope, lift, .24)
        capped = cap(image)
        direct = hi.shoulder(image)
        first = cap(synthetic_layer(image))
        factor = hi.face_cut(first, faces)
        rerendered = cap(synthetic_layer(image * factor)) if factor < 1 else first
        final = hi.shoulder(rerendered)
        height, width = faces.shape
        lines.append(f"CASE,{name},{width},{height},{number(factor)}")
        rows = np.concatenate((image, faces[..., None], capped, direct, final), axis=-1).reshape(-1, 13)
        lines += ["PIX," + ",".join(number(v) for v in row) for row in rows]
    return "\n".join(lines) + "\n"


def generated() -> dict[Path, str]:
    return {CONSTANTS: constants(), FIXTURE: fixture()}


def check_exports() -> None:
    if CONSTANTS.read_text(encoding="utf-8") != constants():
        raise AssertionError("Generated Kotlin constants differ from PC authority")
    expected = fixture().splitlines()
    committed = gzip.decompress(FIXTURE.read_bytes()).decode("utf-8").splitlines()
    if len(expected) != len(committed):
        raise AssertionError("Synthetic fixture shape changed")
    # NumPy wheel/CPU math can differ in the last float32 bits. Keep metadata exact;
    # compare every scalar with a PC regeneration tolerance below the Kotlin boundary.
    for line, (want, got) in enumerate(zip(expected, committed), 1):
        a, b = want.split(","), got.split(",")
        numeric_start = 1 if a[0] == "PIX" else 4 if a[0] == "CASE" else len(a)
        if a[:numeric_start] != b[:numeric_start] or len(a) != len(b):
            raise AssertionError(f"Synthetic fixture layout differs at line {line}")
        if numeric_start < len(a):
            np.testing.assert_allclose(np.array(b[numeric_start:], dtype=float),
                                       np.array(a[numeric_start:], dtype=float),
                                       atol=2e-6, rtol=0, err_msg=f"fixture line {line}")


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--write", action="store_true")
    mode.add_argument("--check", action="store_true")
    args = parser.parse_args()
    if args.write:
        for path, contents in generated().items():
            path.parent.mkdir(parents=True, exist_ok=True)
            if path == FIXTURE:
                path.write_bytes(gzip.compress(contents.encode("utf-8"), mtime=0))
            else:
                path.write_text(contents, encoding="utf-8", newline="\n")
    else:
        check_exports()
    print("Stage Clear protection exports match PC authority" if not args.write else "Wrote synthetic protection exports")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
